CREATE TABLE accounts(id TEXT PRIMARY KEY,type TEXT NOT NULL CHECK(type IN ('QQ','微信')),identifier TEXT NOT NULL,name TEXT NOT NULL DEFAULT '',UNIQUE(type,identifier));
CREATE TABLE games(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE regions(id TEXT PRIMARY KEY,gameId TEXT NOT NULL REFERENCES games(id) ON DELETE CASCADE,name TEXT NOT NULL,UNIQUE(gameId,name));
CREATE TABLE roles(id TEXT PRIMARY KEY,accountId TEXT NOT NULL REFERENCES accounts(id) ON DELETE CASCADE,regionId TEXT NOT NULL REFERENCES regions(id) ON DELETE CASCADE,roleId TEXT NOT NULL,nickname TEXT NOT NULL DEFAULT '',UNIQUE(accountId,regionId,roleId));
CREATE TABLE bans(id TEXT PRIMARY KEY,roleId TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,start INTEGER NOT NULL,end INTEGER NOT NULL DEFAULT 0,permanent INTEGER NOT NULL DEFAULT 0,confirmed INTEGER NOT NULL DEFAULT 0,reason TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',remind INTEGER NOT NULL DEFAULT 1,created INTEGER NOT NULL);
CREATE INDEX ban_role_time ON bans(roleId,start DESC,created DESC,id DESC);
CREATE TABLE attachments(id TEXT PRIMARY KEY,banId TEXT NOT NULL REFERENCES bans(id) ON DELETE CASCADE,file TEXT NOT NULL,mime TEXT NOT NULL);
CREATE TABLE settings(id TEXT PRIMARY KEY,value TEXT NOT NULL);
INSERT INTO settings VALUES('defaultRemind','1');
